INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES ('1', 'About Us', 'about-us', '<h2>About JobNexaa</h2><p>JobNexaa is an independent, authoritative career guidance and employment resource platform dedicated to empowering job seekers with verified job alerts, interview frameworks, resume strategies, and career blueprints.</p><h3>Our Mission</h3><p>To bridge the gap between job seekers and authentic career opportunities through transparent, verified reporting and actionable editorial guides.</p>', 'Learn about JobNexaa mission, background, and verified editorial standards.', 'published', '2026-10-03 10:22:49', '2026-10-06 20:09:26');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES ('2', 'Privacy Policy', 'privacy-policy', '<h2>Privacy Policy</h2><p>Your privacy is important to us. JobNexaa collects minimal log information necessary for security and user experience. We do not sell your personal data.</p>', 'Comprehensive privacy policy and user data protections at JobNexaa.', 'published', '2026-10-03 10:22:49', '2026-10-06 20:09:26');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES ('3', 'Terms & Conditions', 'terms-and-conditions', '<h2>Terms & Conditions</h2><p>By accessing JobNexaa, you agree to comply with our acceptable use policies. All editorial content is protected by international copyright laws.</p>', 'Terms and conditions governing the use of JobNexaa website and services.', 'published', '2026-10-03 10:22:49', '2026-10-06 20:09:26');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES ('4', 'Editorial Disclaimer', 'disclaimer', '<h2>Editorial Disclaimer</h2><p>JobNexaa publishes job alerts for informational purposes. Candidates should verify terms directly with prospective employers. We never charge candidates for job listings.</p>', 'Employment notice and editorial verification disclaimer.', 'published', '2026-10-03 10:22:49', '2026-10-06 20:09:26');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES ('5', 'Contact Support', 'contact', '<h2>Contact Us</h2><p>Have an inquiry, editorial correction, or partnership proposal? Reach out to our team at contact@careernexaa.com.</p>', 'Get in touch with the JobNexaa editorial and administration team.', 'published', '2026-10-03 10:22:49', '2026-10-07 13:54:24');

